Comparing Methods


Code
fit_statistics &lt;- penalized_regression_fit_statistics_combined |&gt;
  mutate(method = case_when(
    str_detect(method, "lasso") ~ "LASSO",
    str_detect(method, "elasticnet") ~ "Elastic Net",
    str_detect(method, "ridge") ~ "Ridge"
  )) |&gt;
  select(method, metric = .metric, estimate = .estimate) |&gt;
  pivot_wider(names_from = metric, values_from = estimate)

fit_stat_cols &lt;- fit_statistics |&gt;
  select(-method) |&gt; 
  names()

fit_statistics |&gt;
  j_gt() |&gt;
  fmt_number(decimals = 3) |&gt;
    tab_style(cell_fill(color = "#e2eee2"),
            cells_body(columns = rmse, rows = rmse == min(rmse))) |&gt;
    tab_style(cell_fill(color = "#e2eee2"),
            cells_body(columns = rsq, rows = rsq == max(rsq))) |&gt;
    tab_style(cell_fill(color = "#e2eee2"),
            cells_body(columns = mae, rows = mae == min(mae))) |&gt;
  tab_style(cell_text(weight = "bold"),
            cells_column_labels()) |&gt;
  cols_label_with(columns = -method, str_to_upper) |&gt;
  cols_label_with(columns = method, str_to_title)








